Subject: [PATCH] klipper: allow reordering actions and commands by drag and
 drop

The only way to change the order of actions, or of the commands in an
action, was to delete and add them again. Actions can now be dragged
among actions, and commands within their own action, in the settings.

BUG: 477382
---
 klipper/actionstreewidget.cpp | 44 +++++++++++++++++++++++++++++++++++
 klipper/actionstreewidget.h   |  5 ++++
 klipper/configdialog.cpp      | 11 +++++++++
 klipper/configdialog.h        |  1 +
 klipper/urlgrabber.h          |  5 ++++
 5 files changed, 66 insertions(+)

diff --git a/klipper/actionstreewidget.cpp b/klipper/actionstreewidget.cpp
index f4ee54e800..d96cd48caf 100644
--- a/klipper/actionstreewidget.cpp
+++ b/klipper/actionstreewidget.cpp
@@ -5,6 +5,8 @@
 */
 #include "actionstreewidget.h"

+#include <QSignalBlocker>
+
 ActionsTreeWidget::ActionsTreeWidget(QWidget *parent)
     : QTreeWidget(parent)
     , m_actionsChanged(-1)
@@ -19,6 +21,48 @@ ActionsTreeWidget::ActionsTreeWidget(QWidget *parent)
         connect(treeModel, &QAbstractItemModel::rowsRemoved, this, &ActionsTreeWidget::onItemChanged);
     }
     setProperty("kcfg_propertyNotify", true);
+    setDragDropMode(QAbstractItemView::InternalMove);
+}
+
+void ActionsTreeWidget::startDrag(Qt::DropActions supportedActions)
+{
+    // Actions can only be moved among actions, and commands only within their own action
+    const QTreeWidgetItem *draggedParent = currentItem() ? currentItem()->parent() : nullptr;
+    const auto setDropEnabled = [](QTreeWidgetItem *item, bool enabled) {
+        item->setFlags(enabled ? item->flags() | Qt::ItemIsDropEnabled : item->flags() & ~Qt::ItemIsDropEnabled);
+    };
+    {
+        const QSignalBlocker blocker(this);
+        setDropEnabled(invisibleRootItem(), !draggedParent);
+        for (int i = 0; i < topLevelItemCount(); ++i) {
+            QTreeWidgetItem *action = topLevelItem(i);
+            setDropEnabled(action, action == draggedParent);
+            for (int j = 0; j < action->childCount(); ++j) {
+                setDropEnabled(action->child(j), false);
+            }
+        }
+    }
+    QTreeWidget::startDrag(supportedActions);
+}
+
+void ActionsTreeWidget::dropEvent(QDropEvent *event)
+{
+    QTreeWidgetItem *item = currentItem();
+    if (!item) {
+        QTreeWidget::dropEvent(event);
+        return;
+    }
+    QTreeWidgetItem *parent = item->parent();
+    const auto indexOf = [this, item](QTreeWidgetItem *parentItem) {
+        return parentItem ? parentItem->indexOfChild(item) : indexOfTopLevelItem(item);
+    };
+    const int from = indexOf(parent);
+    QTreeWidget::dropEvent(event);
+    const int to = indexOf(parent);
+    if (to != -1 && to != from) {
+        setCurrentItem(item);
+        Q_EMIT itemMoved(parent, from, to);
+    }
 }

 void ActionsTreeWidget::onItemChanged()
