+++ b/klipper/configdialog.cpp
@@ -303,6 +303,7 @@ ActionsWidget::ActionsWidget(QWidget *parent)
     connect(m_actionsTree, &QTreeWidget::itemSelectionChanged, this, &ActionsWidget::onSelectionChanged);
     connect(m_actionsTree, &QTreeWidget::itemDoubleClicked, this, &ActionsWidget::onEditAction);
     connect(m_actionsTree, &QTreeWidget::itemChanged, this, &ActionsWidget::onItemChanged);
+    connect(m_actionsTree, &ActionsTreeWidget::itemMoved, this, &ActionsWidget::onItemMoved);

     onSelectionChanged();
 }
@@ -515,6 +516,16 @@ void ActionsWidget::onItemChanged(QTreeWidgetItem *item, int /*col*/)
     }
 }

+void ActionsWidget::onItemMoved(QTreeWidgetItem *parentItem, int from, int to)
+{
+    if (parentItem == nullptr) { // an action was moved
+        m_actionList.move(from, to);
+    } else { // a command was moved within its action
+        m_actionList.at(m_actionsTree->indexOfTopLevelItem(parentItem))->moveCommand(from, to);
+    }
+    Q_EMIT widgetChanged();
+}
+
